INSERT INTO "changelog_entry" ("entry_date", "summary") VALUES
('2026-11-25', 'Les potlucks s''habillent comme le reste du CLHUB : fini le décor de bistrot à part, place aux couleurs du club et au vert de « Manger », et ils suivent maintenant le mode clair. Le mot « repas » qui traînait encore dans leurs écrans et leurs mails est devenu « potluck ».');
